import {chapters,levels} from './story.js';
import {fresh,active,dispatch,complete,restore,award,unlocked} from './engine.js';
const $=id=>document.getElementById(id),SAVE='button-starlight-v2';
let saved={},storageOK=true;
try{saved=JSON.parse(localStorage.getItem(SAVE)||'{}')||{};}catch{storageOK=false;}
let states=levels.map((_,i)=>restore(i,saved.states?.[i]));
let best=levels.map((_,i)=>Number.isInteger(saved.best?.[i])?Math.max(0,Math.min(3,saved.best[i])):0);
let current=Number.isInteger(saved.current)?Math.max(0,Math.min(unlocked(states,best),saved.current)):0;
let selected=null,world=null,sound=false,audio=null,holdStart=null,holdRAF=null,wasPlayed=saved.started===true;
function save(){try{localStorage.setItem(SAVE,JSON.stringify({started:true,current,states,best}));}catch{storageOK=false;}}
function say(text){$('feedback').textContent=text;}
function ping(kind='tap',note=''){if(!sound)return;try{audio ||=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=kind==='win'?784:kind==='no'?220:kind==='note'?({low:392,mid:523,high:659}[note]||523):659;g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.25);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.26);}catch{}}
const symbols={bell:'♧',scarf:'≈',hero:'◇',battery:'▥',lamp:'☀',star:'✦',door:'▯',note:'♪',wheel:'◉',mirror:'◈',spool:'⊚',robot:'▣',beacon:'△',switch:'●',boat:'⌁',gear:'⚙',bridge:'═',cloth:'▱',mushroom:'♧'};
function earnedItems(){return chapters.filter((_,i)=>complete(states[i*6+5])||best[i*6+5]>0).map(c=>c.item);}
function visibleObjects(){const l=levels[current],s=states[current];return l.objects.filter(o=>(o.after||0)<=s.step);}
function doneItems(){const l=levels[current],s=states[current];return new Set(l.steps.slice(0,s.step).filter(r=>r.kind==='move').map(r=>r.item));}
function updateObjects(){const s=states[current],st=active(s),used=doneItems();$('objects').innerHTML=visibleObjects().map(o=>`<button class="object ${selected===o.id?'selected':''} ${used.has(o.id)?'used':''}" data-item="${o.id}" aria-pressed="${selected===o.id}"><em aria-hidden="true">${symbols[o.type]||'◇'}</em>${o.label}${s.circuit[o.id]?'<span class="state">ON</span>':(st?.kind==='dial'&&st.item===o.id)?`<span class="state">${s.dials[o.id]||0}/3</span>`:used.has(o.id)?'<span class="state">✓</span>':''}</button>`).join('')+`<button class="object secret" data-item="__secret"><em aria-hidden="true">✧</em>${s.secret?'기억 다시 읽기':'주변 작은 빛 살펴보기'}</button>`;
 $('selection').hidden=!selected;if(selected)$('selection').textContent=`${levels[current].objects.find(o=>o.id===selected)?.label||selected} 선택 · 사용할 곳을 눌러요`;
 const isHold=st?.kind==='hold';$('hold-button').hidden=!isHold;$('hold-button').textContent=isHold?`${levels[current].objects.find(o=>o.id===st.item)?.label||''} · 길게 눌러 힘 모으기`:'';world?.setSelected(selected);
}
function render({message,dialogue}={}){cancelHold();selected=null;const l=levels[current],s=states[current],c=chapters[l.chapter];document.documentElement.style.setProperty('--accent',c.color);$('chapter-tag').textContent=`CHAPTER ${String(l.chapter+1).padStart(2,'0')} / ${c.tag}`;$('chapter-title').textContent=c.title;$('stage-number').textContent=`STAGE ${String(current+1).padStart(2,'0')} / 30`;$('place').textContent=l.place;$('level-title').textContent=l.title;$('mission').textContent=l.mission;$('dialogue').textContent=dialogue||(s.step?l.steps[s.step-1].done:l.intro);$('hint-count').textContent=s.hints;$('secret-status').textContent=`숨은 기억 ${Number(s.secret)} / 1`;$('step-track').innerHTML=l.steps.map((_,i)=>`<i class="${i<s.step?'done':''}"></i>`).join('');$('step-track').setAttribute('aria-label',`${l.steps.length}개 행동 중 ${s.step}개 해결`);$('journey-count').textContent=`${String(states.filter(complete).length).padStart(2,'0')} / 30`;$('journey-bar').firstElementChild.style.width=`${states.filter(complete).length/30*100}%`;$('continue').hidden=!complete(s);$('continue').textContent=current===29?'모험 지도와 도감 보기 →':'다음 이야기 →';$('bag-items').innerHTML=earnedItems().map(item=>`<small>✧ ${item}</small>`).join('')||'<small class="empty">이야기를 지나며 친구들의 선물이 모여요.</small>';say(message||(complete(s)?'이 이야기를 완성했어요. 놓친 작은 빛도 찾아볼 수 있어요.':'장면과 이야기를 살펴보세요. 물건을 눌러 선택할 수 있어요.'));updateObjects();world?.build(l,s);save();}
function clearDialog(){const s=states[current],l=levels[current];best[current]=Math.max(best[current],award(s));save();$('clear-tag').textContent=current===29?'THE FIRST ADVENTURE, COMPLETE':(current+1)%6===0?'A CHAPTER TO REMEMBER':'A LITTLE LIGHT, FOUND';$('clear-stars').textContent='★'.repeat(award(s))+'☆'.repeat(3-award(s));$('clear-stars').setAttribute('aria-label',`별 ${award(s)}개 획득`);$('clear-title').textContent=current===29?'우리가 돌아갈 곳':(current+1)%6===0?'한 조각 더, 마음에.':'작은 이야기를 완성했어요.';$('clear-story').textContent=l.outro;$('chapter-memory').hidden=(current+1)%6!==0;if((current+1)%6===0)$('chapter-memory').textContent=`기억 ${l.chapter+1} · ${chapters[l.chapter].memory}\n${chapters[l.chapter].quote}\n가방에 ${chapters[l.chapter].item}을 담았어요.`;$('next').textContent=current===29?'완성한 모험 둘러보기 →':(current+1)%6===0?'다음 챕터로 →':'다음 이야기 →';$('clear-dialog').showModal();}
function apply(a){const s=states[current],r=dispatch(s,a);states[current]=r.state;if(r.secret){render({message:r.message});if(complete(r.state)){best[current]=Math.max(best[current],award(r.state));save();}ping('win');return;}
 if(r.changed){render({message:r.message});ping(r.advanced?'win':'note',a.item);if(r.advanced&&complete(r.state))clearDialog();}else{say(r.message);ping('no');}}
function choose(id,eventKind='tap',elapsed=0){const s=states[current];if(id==='__secret'){apply({kind:'secret',item:id});return;}const st=active(s);
 if(selected&&id!==selected){let item=selected;selected=null;apply({kind:'move',item,target:id});updateObjects();return;}
 if(selected===id){selected=null;updateObjects();say('선택을 취소했어요.');return;}
 if(st?.kind==='hold'&&st.item===id){if(eventKind==='hold')apply({kind:'hold',item:id,elapsed});else say('이 장치는 길게 눌러야 해요. 아래의 “길게 눌러 힘 모으기” 버튼도 사용할 수 있어요.');return;}
 const movable=levels[current].steps.some((r,i)=>i>=s.step&&r.kind==='move'&&r.item===id);
 if(movable){selected=id;updateObjects();say(`${levels[current].objects.find(o=>o.id===id)?.label} 선택! 사용할 곳을 눌러 주세요.`);ping();return;}
 apply({kind:'tap',item:id});}
$('objects').addEventListener('click',e=>{const b=e.target.closest('[data-item]');if(b)choose(b.dataset.item);});
function cancelHold(){holdStart=null;if(holdRAF)cancelAnimationFrame(holdRAF);holdRAF=null;$('hold-progress').hidden=true;}
function startHold(id,fromButton=false){const st=active(states[current]);if(st?.kind!=='hold'||st.item!==id)return;cancelHold();holdStart={time:performance.now(),id,fromButton};$('hold-progress').hidden=false;const tick=()=>{if(!holdStart)return;const elapsed=performance.now()-holdStart.time;$('hold-progress').firstElementChild.style.width=`${Math.min(1,elapsed/st.duration)*100}%`;if(elapsed>=st.duration&&holdStart.fromButton){const item=holdStart.id;cancelHold();apply({kind:'hold',item,elapsed:st.duration});}else holdRAF=requestAnimationFrame(tick);};tick();}
const holdBtn=$('hold-button');holdBtn.addEventListener('pointerdown',e=>{if(e.button!==0)return;const st=active(states[current]);if(st?.kind==='hold'){e.preventDefault();holdBtn.setPointerCapture(e.pointerId);startHold(st.item,true);}});for(const name of ['pointerup','pointercancel','lostpointercapture'])holdBtn.addEventListener(name,cancelHold);holdBtn.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&!e.repeat){e.preventDefault();const st=active(states[current]);if(st?.kind==='hold')startHold(st.item,true);}});holdBtn.addEventListener('keyup',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();cancelHold();}});holdBtn.addEventListener('blur',cancelHold);window.addEventListener('blur',cancelHold);document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelHold();});
$('hint').onclick=()=>{const s=states[current],st=active(s);if(!st){say('이 장면은 완성됐어요. 숨은 기억도 찾아 보세요.');return;}s.hints++;$('hint-count').textContent=s.hints;const pref=s.hints===1?'이야기 속에 단서가 있어요. 현재 목표부터 살펴봐요. ':'';say(pref+st.clue);save();};
$('reset').onclick=()=>{cancelHold();states[current]=fresh(current);render({message:'이 장면만 처음부터 시작해요. 다음 장면의 잠금과 모은 별은 유지돼요.'});};
function openMap(){const max=unlocked(states,best);$('chapter-map').innerHTML=chapters.map((c,ci)=>`<section class="map-chapter"><h3>${String(ci+1).padStart(2,'0')} · ${c.title}</h3><p>${c.cast}</p><div class="map-nodes">${levels.filter(l=>l.chapter===ci).map(l=>{const i=l.id-1,solved=complete(states[i]);return `<button data-level="${i}" class="${solved?'solved ':''}${i===current?'current':''}" ${i>max?'disabled':''} aria-label="${l.id}단계 ${l.title}${i>max?' 잠김':''}"><span>${i>max?'·':String(l.id).padStart(2,'0')}</span><small>${best[i]?'★'.repeat(best[i]):i>max?'LOCK':'—'}</small></button>`;}).join('')}</div></section>`).join('');$('save-note').textContent=storageOK?'진행은 이 브라우저에 자동으로 저장돼요.':'이 브라우저에서 저장할 수 없어 창을 닫으면 진행을 잃을 수 있어요.';$('map-dialog').showModal();}
$('map').onclick=openMap;$('brand').onclick=e=>{e.preventDefault();openMap();};$('chapter-map').onclick=e=>{const b=e.target.closest('[data-level]');if(!b||b.disabled)return;const i=Number(b.dataset.level);if(i>unlocked(states,best))return;current=i;$('map-dialog').close();render();window.scrollTo({top:0,behavior:'instant'});};
$('book').onclick=()=>{const ch=chapters.map((c,i)=>{const done=complete(states[i*6+5])||best[i*6+5]>0;return `<article class="memory ${done?'':'locked'}"><h3>${done?'✦':'◇'} ${done?c.memory:'아직 만나지 않은 기억'}</h3><p>${done?c.quote:`${c.title}의 마지막 이야기를 완성하면 열려요.`}</p><small>${done?`가방 속 선물 · ${c.item}`:`CHAPTER ${i+1}`}</small></article>`;}).join('');const secrets=states.map((s,i)=>s.secret?`<div class="memory-secret"><b>${String(i+1).padStart(2,'0')} · ${levels[i].title}</b><br>${levels[i].secret}</div>`:'').join('');$('memory-list').innerHTML=ch+(secrets?`<h3>발견한 숨은 기억 · ${states.filter(s=>s.secret).length}/30</h3>${secrets}`:'');$('memory-dialog').showModal();};
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();
function next(){if(current===29){openMap();return;}if(!complete(states[current]))return;current++;render();window.scrollTo({top:0,behavior:'instant'});}
$('next').onclick=()=>{$('clear-dialog').close();next();};$('continue').onclick=next;$('story-again').onclick=()=>{$('dialogue').textContent=levels[current].intro;};$('rotate').onclick=()=>world?.rotate();$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'♪ ON':'♪ OFF';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'소리 끄기':'소리 켜기');if(sound)ping();};$('start').onclick=()=>{$('intro-dialog').close();save();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){selected=null;updateObjects();}});
render();if(!wasPlayed)$('intro-dialog').showModal();
try{const {World}=await import('./world.js');world=new World($('canvas'),a=>{if(a.kind==='move'){selected=null;apply(a);}else choose(a.item,a.kind,a.elapsed);},(kind,id)=>{if(kind==='start')startHold(id);else cancelHold();});world.build(levels[current],states[current]);}catch(e){$('scene-error').hidden=false;console.error('3D initialization failed',e);}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
